/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import { loadFont, loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
} from "react";
import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

interface InputStyleContext {
  idleBorder: string;
  hoverBorder: string;
  activeBorder: string;
  invalidBorder: string;
  ring: string;
  invalidRing: string;
  background: string;
  hoverBackground: string;
  foreground: string;
  mutedForeground: string;
}

function inputStyleContext(theme: KitTheme): InputStyleContext {
  return {
    idleBorder: theme.input,
    hoverBorder: mixOklch(theme.input, theme.foreground, 0.18),
    activeBorder: theme.ring,
    invalidBorder: theme.destructive,
    ring: mixOklch(theme.background, theme.ring, 0.5),
    invalidRing: mixOklch(theme.background, theme.destructive, 0.4),
    background: theme.background,
    hoverBackground: mixOklch(theme.background, theme.muted, 0.4),
    foreground: theme.foreground,
    mutedForeground: theme.mutedForeground,
  };
}

const { fontFamily: SANS } = loadFont("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});

// --- The stage -------------------------------------------------------------
//
// Geometry and timing were read off a 712×402, 30fps screen recording, in its
// own pixels ("ref px"). They are multiplied out to the composition's pixels
// (`u`) before anything is laid out: laying out at ref size and scaling the box
// up lets Chrome round every left/top to a whole *ref* pixel, which is a 1.8px
// jump per frame at 720p. Everything that moves, moves by `transform`.
//
// "World" is the recording's frame 0. The camera only pans (the pill is 187px
// tall on every frame), so a world point lands on screen at `world + cam`.

const REF_W = 712;
const REF_H = 402;
/** Recorded fps: every time below is in recorded frames. */
const REF_FPS = 30;

/**
 * The pan, per recorded frame, measured by registering each frame on the last.
 * The source's one-frame 7.5px hop on the first keystroke is folded into the
 * text's position instead, so the pan starts from rest.
 */
const CAM_X = [
  0, 0, 0, 0, 0, 0, 0, 0, -0.2, -0.8, -1.9, -3.6, -5.7, -8.5, -12, -16, -20.9,
  -26.6, -33.1, -40.4, -49, -58.6, -69.6, -82.1, -96.2, -112.1, -130, -150.3,
  -173.3, -199.4, -229.1, -262.8, -300.9, -343.6, -390.9, -441.8, -494.7,
  -547.3, -597.4, -643.5, -685, -721.8, -754.2, -782.6, -807.7, -829.7, -849.1,
  -866.2, -881.2, -894.5, -906.2, -916.5, -925.6, -933.5, -940.4, -946.4,
  -951.5, -955.7, -959.3, -962.2, -964.4, -966.2, -967.3, -968, -968.2,
];
const CAM_X_END = CAM_X[CAM_X.length - 1];
/** The rise: already moving on frame 0, an exponential settle onto -35. */
const CAM_Y_END = -35;
const camY = (f: number) => CAM_Y_END * (1 - Math.exp(-0.23 * Math.max(0, f)));

/** The input pill, world ref px. Fully round ends. */
const PILL = { x: 142, y: 142, w: 1273, h: 187 };
/** The prompt line: Inter 500 at 127px, its line box's top at y 171. */
const TEXT = { x: 198.9, top: 171, size: 127, tracking: 3 };
/** The caret: a 9px bar from y 180 to 307, 9px past the last glyph. */
const CARET = { w: 9, top: 180, h: 127, gap: 9 };
/** The send button: a 168px disc, 11px inside the pill's right end. */
const SEND = { cx: 1320.2, cy: 239, d: 168 };
/** It shrinks to an 88px badge, whose mark then carries the lockup. */
const BADGE = 88;
/**
 * The lockup's proportions, as a wordmark would set them. The name is
 * lowercase, so the mark is sized and centred on its x-height (Inter: 0.546em,
 * centred 0.091em below the line box's middle at line-height 1), not its em
 * box: the mark stands as tall as a capital (1.33 x-heights), the gap is 0.24em.
 */
const WORD = { size: 64, gap: 0.24, xHeight: 0.546, xDrop: 0.091 };
const MARK_H = 1.33 * WORD.xHeight * WORD.size;
const MARK_W = (MARK_H * 464) / 409;

/** The recording's 11 keystrokes; anything longer keeps typing at 3 frames a key. */
const KEYS = [3, 6, 9, 13, 16, 19, 22, 26, 29, 32, 35];
const keyAt = (i: number) =>
  i < KEYS.length ? KEYS[i] : KEYS[KEYS.length - 1] + 3 * (i - KEYS.length + 1);

/** A moderate decelerate: arrives at rest without spending frames on nothing. */
const SETTLE = Easing.bezier(0.2, 0.6, 0.35, 1);
const IN_OUT = Easing.bezier(0.45, 0, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** Linear lookup into a per-frame table, holding its ends. */
function table(t: readonly number[], f: number): number {
  if (f <= 0) return t[0];
  if (f >= t.length - 1) return t[t.length - 1];
  const lo = Math.floor(f);
  return t[lo] + (t[lo + 1] - t[lo]) * (f - lo);
}

/** The the library mark — a lens body and its shutter wedge. */
function Mark({ size, fill }: { size: number; fill: string }) {
  return (
    <svg
      width={size}
      height={(size * 409) / 464}
      viewBox="0 0 464 409"
      aria-hidden
      style={{ display: "block" }}
    >
      <rect x="27.5" y="0" width="409" height="409" rx="96" fill={fill} />
    </svg>
  );
}

interface DiscLook {
  /** Drawn at this size in px, then scaled by `scale` — never resized. */
  size: number;
  scale: number;
  fill: string;
  accent: string;
  arrow: number;
  mark: number;
  glow: number;
  ring: string;
}

/**
 * The send button and, later, the badge. One drawing, so the hand-off from the
 * camera's world to the lockup is pixel-identical.
 */
function Disc({
  size,
  scale,
  fill,
  accent,
  arrow,
  mark,
  glow,
  ring,
}: DiscLook) {
  return (
    <div
      style={{
        position: "absolute",
        left: -size / 2,
        top: -size / 2,
        width: size,
        height: size,
        borderRadius: "50%",
        background: fill,
        boxShadow: `inset 0 0 0 ${size * 0.012}px ${ring}`,
        overflow: "hidden",
        transform: `scale(${scale})`,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: glow,
          background: `radial-gradient(75% 60% at 50% 100%, ${withAlpha(accent, 0.55)} 0%, ${withAlpha(accent, 0.18)} 50%, ${withAlpha(accent, 0)} 100%)`,
        }}
      />
      {/* Send: the round-capped lucide up-arrow, drawn at disc scale. */}
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        aria-hidden
        style={{
          position: "absolute",
          inset: 0,
          opacity: arrow,
          transform: `scale(${0.5 + 0.06 * arrow})`,
        }}
      >
        <g
          fill="none"
          stroke={accent}
          strokeWidth={2.4}
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M12 19V5" />
          <path d="M5.5 11.5L12 5l6.5 6.5" />
        </g>
      </svg>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: mark,
          transform: `scale(${0.88 + 0.12 * mark})`,
        }}
      >
        <Mark size={size * 0.5} fill={accent} />
      </div>
    </div>
  );
}

export interface PromptMarkProps {
  /** What gets typed into the prompt. About 11 characters fits the pan. */
  text?: string;
  /** The name in the closing lockup. */
  name?: string;
  theme?: Partial<KitTheme>;
  /** The scene opens in this mode and flashes into the other. */
  mode?: "light" | "dark";
  fontFamily?: string;
}

/**
 * A prompt types into a pill while the camera rides the caret, pans onto the
 * send button, the arrow becomes the mark, the room flashes into the other mode
 * inside an accent bloom, and the badge settles into a logo lockup.
 */
function PromptMarkScene({
  text = "Ship a demo",
  name = "Acme",
  theme,
  mode = "dark",
  fontFamily = "Default",
}: PromptMarkProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const f = (frame * REF_FPS) / fps;
  const t = useKitTheme(theme, mode);
  const ui = inputStyleContext(t);
  const face = resolveFont(fontFamily) ?? SANS;
  const rendering = getRemotionEnvironment().isRendering;

  // The composition's px per ref px, and the stage's offset inside the frame.
  const u = Math.max(width / REF_W, height / REF_H);
  const ox = (width - REF_W * u) / 2;
  const oy = (height - REF_H * u) / 2;
  const camX = table(CAM_X, f);
  const cy = camY(f);
  const at = (wx: number, wy: number) => [
    (wx + camX) * u + ox,
    (wy + cy) * u + oy,
  ];

  // --- palette: the mode it opens in, and the one the flash lands in ------
  const accent = t.primary;
  const endPage = t.foreground;
  const endInk = t.background;
  const glowColor = mixOklch(t.background, accent, 0.42);

  // --- typing --------------------------------------------------------------
  const chars = Array.from(text);
  const typed = chars.filter((_, i) => f >= keyAt(i)).length;
  const lastKey = typed ? keyAt(typed - 1) : 0;
  const doneAt = keyAt(Math.max(0, chars.length - 1));
  const cool = (k: number) => interpolate(f - k, [0, 2], [0, 1], clamp);
  const caretOn = f < doneAt + 1 || Math.floor(f - lastKey) % 16 < 7;
  const pillOpacity = interpolate(f, [55, 60], [1, 0], clamp);

  // --- send → mark → badge -------------------------------------------------
  const flash = interpolate(f, [107, 118], [0, 1], clamp);
  const look: DiscLook = {
    size: SEND.d * u,
    scale: interpolate(f, [93, 116], [1, BADGE / SEND.d], {
      ...clamp,
      easing: IN_OUT,
    }),
    fill: t.foreground,
    accent,
    arrow: interpolate(f, [66, 73], [1, 0], clamp),
    mark: interpolate(f, [72, 90], [0, 1], { ...clamp, easing: SETTLE }),
    glow:
      interpolate(f, [74, 93], [0, 1], clamp) *
      interpolate(f, [100, 116], [1, 0], clamp),
    // On the flashed page the badge is page-coloured, so a hairline draws it.
    ring: withAlpha(mixOklch(endPage, endInk, 0.14), flash),
  };

  // The cursor rises from below the frame and settles under the button.
  const cursorRise = interpolate(f, [36, 64], [0, 1], {
    ...clamp,
    easing: SETTLE,
  });
  const cursorOpacity = interpolate(f, [80, 96], [1, 0], clamp);

  // --- the flash: the room lifts into the other mode inside an accent bloom
  const bloomGrow = interpolate(f, [107, 118], [0.25, 1], {
    ...clamp,
    easing: SETTLE,
  });
  const bloomOut = interpolate(f, [118, 136], [0, 1], clamp);
  const bloomOpacity =
    interpolate(f, [107, 110], [0, 1], clamp) * (1 - bloomOut);

  // --- the lockup ----------------------------------------------------------
  const p = interpolate(f, [118, 142], [0, 1], { ...clamp, easing: IN_OUT });
  const word = interpolate(f, [128, 150], [0, 1], {
    ...clamp,
    easing: SETTLE,
  });
  const inLockup = f >= 118;

  const [sx, sy] = at(SEND.cx, SEND.cy);
  // Where the camera leaves the badge; the lockup starts from exactly here.
  const restX = (SEND.cx + CAM_X_END) * u + ox;
  const restY = (SEND.cy + CAM_Y_END) * u + oy;
  const badgePx = BADGE * u;
  const markPx = MARK_W * u;
  // The badge's mark, as drawn on the disc, is half the badge wide; it grows
  // from exactly that into the lockup's mark while the disc fades out.
  const markScale = interpolate(p, [0, 1], [(0.5 * BADGE) / MARK_W, 1]);
  const discFade = interpolate(p, [0, 0.55], [1, 0], clamp);

  // The prompt line. Chrome rounds a glyph's vertical origin to a whole device
  // pixel, so a line riding the camera's rise would climb in 1px steps. Two
  // copies a pixel apart, cross-faded and summed (plus-lighter), put it exactly
  // where it belongs instead.
  const lineX = (TEXT.x + camX) * u + ox;
  const lineY = (TEXT.top + cy) * u + oy;
  const y0 = Math.floor(lineY);
  const frac = lineY - y0;
  const line: ReactNode = (
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        height: TEXT.size * u,
        lineHeight: `${TEXT.size * u}px`,
        fontFamily: face,
        fontSize: TEXT.size * u,
        fontWeight: 500,
        letterSpacing: TEXT.tracking * u,
        whiteSpace: "pre",
        textRendering: "geometricPrecision",
      }}
    >
      {chars.slice(0, typed).map((ch, i) => (
        <span
          // biome-ignore lint/suspicious/noArrayIndexKey: a fixed string
          key={i}
          style={{ color: mixOklch(accent, ui.foreground, cool(keyAt(i))) }}
        >
          {ch}
        </span>
      ))}
      <span
        style={{
          display: "inline-block",
          width: CARET.w * u,
          height: CARET.h * u,
          marginLeft: (typed ? CARET.gap : CARET.gap + 9.5) * u,
          marginTop: (CARET.top - TEXT.top) * u,
          borderRadius: u,
          background: typed
            ? mixOklch(accent, ui.foreground, cool(lastKey))
            : accent,
          opacity: caretOn ? 1 : 0,
        }}
      />
    </div>
  );
  const [px, py] = at(PILL.x, PILL.y);

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ background: t.background, overflow: "hidden" }}
    >
      {/* The room: fixed to the screen, lit in the accent from the top-right. */}
      <AbsoluteFill
        showInTimeline={false}
        style={{
          background: `radial-gradient(130% 95% at 100% 0%, ${glowColor} 0%, ${withAlpha(glowColor, 0.45)} 22%, ${withAlpha(glowColor, 0.12)} 48%, ${withAlpha(glowColor, 0)} 78%)`,
        }}
      />

      {pillOpacity > 0 ? (
        <>
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: PILL.w * u,
              height: PILL.h * u,
              borderRadius: (PILL.h * u) / 2,
              background: mixOklch(ui.background, t.card, 0.8),
              boxShadow: `inset 0 0 0 ${Math.max(1, u)}px ${mixOklch(ui.idleBorder, ui.foreground, 0.12)}`,
              transform: `translate(${px}px, ${py}px)`,
              opacity: pillOpacity,
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              isolation: "isolate",
              opacity: pillOpacity,
            }}
          >
            {[0, 1].map((k) => (
              <div
                key={k}
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  transform: `translate(${lineX}px, ${y0 + k}px)`,
                  opacity: k ? frac : 1 - frac,
                  mixBlendMode: "plus-lighter",
                  willChange: rendering ? undefined : "transform",
                }}
              >
                {line}
              </div>
            ))}
          </div>
        </>
      ) : null}

      {/* The flash and its bloom. */}
      <AbsoluteFill
        showInTimeline={false}
        style={{ background: endPage, opacity: flash }}
      />
      {bloomOpacity > 0 ? (
        <div
          style={{
            position: "absolute",
            left: -250 * u,
            top: -270 * u,
            width: 500 * u,
            height: 540 * u,
            borderRadius: "50%",
            background: `radial-gradient(closest-side, ${mixOklch(accent, t.primaryForeground, 0.12)} 0%, ${accent} 50%, ${withAlpha(accent, 0)} 100%)`,
            filter: `blur(${24 * u}px)`,
            opacity: bloomOpacity,
            transform: `translate(${restX}px, ${restY}px) scale(${bloomGrow * (1 + 0.12 * bloomOut)})`,
          }}
        />
      ) : null}

      {!inLockup ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transform: `translate(${sx}px, ${sy}px)`,
          }}
        >
          <Disc {...look} />
        </div>
      ) : null}

      {f >= 36 && cursorOpacity > 0 ? (
        <svg
          width={26 * u}
          height={42 * u}
          viewBox="-1 -1 13 21"
          aria-hidden
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            opacity: cursorOpacity,
            transform: `translate(${sx + 29 * u}px, ${sy + (198 - 145 * cursorRise) * u}px)`,
          }}
        >
          <path
            d="M0 0V16.2L3.9 12.6L6.6 18.7L9.1 17.6L6.5 11.6H11.6Z"
            fill="#000000"
            stroke="#ffffff"
            strokeWidth={1}
            strokeLinejoin="round"
          />
        </svg>
      ) : null}

      {/* The lockup: the badge slides over and the name follows it out. */}
      {inLockup ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width,
            height: badgePx,
            display: "flex",
            justifyContent: "center",
            // A transform, not `top`: a fractional top would be rounded and
            // the badge would hop on the frame it changes hands.
            transform: `translateY(${restY - badgePx / 2}px)`,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              height: badgePx,
              // Percent is of this row: shifting by half of it less half the
              // badge parks the badge on the frame's centre without measuring
              // the name; the last term starts it where the camera left it.
              transform: `translateX(calc(${(1 - p) * 50}% - ${((1 - p) * markPx) / 2}px + ${(1 - p) * (restX - width / 2)}px))`,
            }}
          >
            <div
              style={{
                position: "relative",
                width: markPx,
                height: badgePx,
                flexShrink: 0,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {discFade > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    left: markPx / 2,
                    top: badgePx / 2,
                    opacity: discFade,
                  }}
                >
                  <Disc {...look} mark={0} />
                </div>
              ) : null}
              <div style={{ transform: `scale(${markScale})` }}>
                <Mark size={markPx} fill={accent} />
              </div>
            </div>
            <span
              style={{
                marginLeft: WORD.gap * WORD.size * u,
                fontFamily: face,
                fontSize: WORD.size * u,
                fontWeight: 600,
                letterSpacing: -0.025 * WORD.size * u,
                lineHeight: 1,
                color: endInk,
                whiteSpace: "pre",
                textRendering: "geometricPrecision",
                opacity: word,
                // Lift the x-height's centre onto the mark's centre (static).
                transform: `translate(${18 * u * (1 - word)}px, ${-WORD.xDrop * WORD.size * u}px)`,
              }}
            >
              {name}
            </span>
          </div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
}

